
import json
import re
from html import unescape
from urllib.parse import urljoin

SITE = "https://careers.hcahealthcare.com/search/information-technology/jobs"
EXTRA_HOSTS = []


def html_to_text(value):
    value = unescape(value or "")
    value = re.sub(r"(?is)<(?:script|style)\b[^>]*>.*?</(?:script|style)>", " ", value)
    value = re.sub(r"(?i)<li\b[^>]*>", "\n- ", value)
    value = re.sub(
        r"(?i)</?(?:p|div|br|h[1-6]|ul|ol|table|tr|section|article)\b[^>]*>",
        "\n",
        value,
    )
    value = re.sub(r"(?s)<[^>]+>", " ", value)
    value = unescape(value).replace("\xa0", " ")
    value = re.sub(r"[ \t\r\f\v]+", " ", value)
    value = re.sub(r" *\n *", "\n", value)
    value = re.sub(r"\n{3,}", "\n\n", value)
    return value.strip()

def json_ld_objects(value):
    scripts = re.findall(
        r'<script[^>]+type=["\']application/ld\+json["\'][^>]*>(.*?)</script>',
        value,
        re.I | re.S,
    )
    for raw in scripts:
        try:
            data = json.loads(unescape(raw).strip())
        except (TypeError, ValueError):
            continue
        pending = data if isinstance(data, list) else [data]
        while pending:
            obj = pending.pop(0)
            if not isinstance(obj, dict):
                continue
            graph = obj.get("@graph")
            if isinstance(graph, list):
                pending.extend(graph)
            if obj.get("@type") == "JobPosting":
                yield obj


def address_text(job_location):
    if isinstance(job_location, list):
        job_location = job_location[0] if job_location else None
    if not isinstance(job_location, dict):
        return None
    address = job_location.get("address")
    if isinstance(address, str):
        return address.strip() or None
    if not isinstance(address, dict):
        return None
    parts = [
        address.get("addressLocality"),
        address.get("addressRegion"),
        address.get("postalCode"),
        address.get("addressCountry"),
    ]
    parts = [str(part).strip() for part in parts if part]
    return ", ".join(parts) if parts else None


def posting_links(page):
    found = []
    seen = set()
    for href in re.findall(r'href=["\']([^"\']+)["\']', page, re.I):
        href = unescape(href)
        absolute = urljoin(SITE, href)
        if not re.match(
            r"^https://careers\.hcahealthcare\.com/jobs/\d+(?:-[^?#]+)?(?:[?#].*)?$",
            absolute,
            re.I,
        ):
            continue
        absolute = absolute.split("#", 1)[0].split("?", 1)[0]
        if absolute not in seen:
            seen.add(absolute)
            found.append(absolute)
    return found


